INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x0fesa63a4jdmnw3q9','note','published','public',1773778513,1773778513,'A Quiet Saturday After a Busy Week',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind."}]},{"type":"paragraph","content":[{"type":"text","text":"Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down."}]},{"type":"moreBreak"},{"type":"paragraph","content":[{"type":"text","text":"What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything."}]},{"type":"paragraph","content":[{"type":"text","text":"A good day does not always need a headline. Sometimes it only needs enough room to happen."}]}]}','<p>Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.</p><p>Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down.</p><!--more--><p>What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything.</p><p>A good day does not always need a headline. Sometimes it only needs enough room to happen.</p>','Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind. Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down. What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything. A good day does not always need a headline. Sometimes it only needs enough room to happen.',NULL,'Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.
