INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a68q9fqaar059z2f7nw8h','quote','published','public',NULL,NULL,'From Basho','https://en.wikiquote.org/wiki/Matsuo_Basho','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable."}]}]}','<p>I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable.</p>','I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable.','Every day is a journey, and the journey itself is home.',NULL,NULL,NULL,'pst_01km8a68q9fqaar059z2f7nw8h',NULL,1754987400,1754987400,1773778516,1773778516);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x1fesa63a85y7happr','note','published','public',NULL,NULL,'The Hallway Light Took 12 Minutes and 3 Months',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie."}]},{"type":"paragraph","content":[{"type":"text","text":"Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task."}]}]}','<p>The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.</p><p>Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was.</p><p>This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.</p>','The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie. Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was. This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.',NULL,'The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a68q9fqaar05jgkv6y1aj','quote','published','public',NULL,NULL,'From Marcus Aurelius','https://en.wikiquote.org/wiki/Marcus_Aurelius','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Good sentence for the weeks when nothing arrives in the right order and everything needs a little more effort than expected."}]}]}','<p>Good sentence for the weeks when nothing arrives in the right order and everything needs a little more effort than expected.</p>','Good sentence for the weeks when nothing arrives in the right order and everything needs a little more effort than expected.','The art of life is more like wrestling than dancing.',NULL,NULL,NULL,'pst_01km8a68q9fqaar05jgkv6y1aj',NULL,1756902000,1756902000,1773778518,1773778518);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x1fesa63amct0xvpaq','note','published','public',NULL,NULL,'Current Tea Rotation',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The kitchen shelf is doing a lot of work right now."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jasmine for late afternoons"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Black tea when I need to become a person quickly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mint tea after dinner when I want the day to stop talking"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing profound here. I just like having a small system for ordinary comfort."}]}]}','<p>The kitchen shelf is doing a lot of work right now.</p><ul><li><p>Jasmine for late afternoons</p></li><li><p>Black tea when I need to become a person quickly</p></li><li><p>Mint tea after dinner when I want the day to stop talking</p></li></ul><p>Nothing profound here. I just like having a small system for ordinary comfort.</p>','The kitchen shelf is doing a lot of work right now. Jasmine for late afternoons Black tea when I need to become a person quickly Mint tea after dinner when I want the day to stop talking Nothing profound here. I just like having a small system for ordinary comfort.',NULL,'The kitchen shelf is doing a lot of work right now.
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a68q9fqaar05yjag6jx6t','link','published','public',NULL,NULL,'Serious Eats on tomato and egg soup','https://www.seriouseats.com/tomato-egg-drop-soup-recipe-8705599','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the kind of recipe I trust on a tired weeknight. Short ingredient list, no drama, and it tastes like you tried harder than you did."}]}]}','<p>This is the kind of recipe I trust on a tired weeknight. Short ingredient list, no drama, and it tastes like you tried harder than you did.</p>','This is the kind of recipe I trust on a tired weeknight. Short ingredient list, no drama, and it tastes like you tried harder than you did.',NULL,NULL,5,NULL,'pst_01km8a68q9fqaar05yjag6jx6t',NULL,1758130200,1758130200,1773778520,1773778520);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x1fesa63av1qd3fy3v','note','published','public',NULL,1773778521,'What I Actually Use My Notebook For',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mostly three things"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shopping lists"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fragments I do not trust my phone with"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The first ugly version of an idea"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away."}]}]}','<p>I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.</p><h2>Mostly three things</h2><ol><li><p>Shopping lists</p></li><li><p>Fragments I do not trust my phone with</p></li><li><p>The first ugly version of an idea</p></li></ol><p>That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.</p>','I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways. Mostly three things Shopping lists Fragments I do not trust my phone with The first ugly version of an idea That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.',NULL,'I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.
