INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x1fesa63b4teq8ngh6','note','published','public',NULL,NULL,'Bought Too Many Lemons Again',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be."}]},{"type":"paragraph","content":[{"type":"text","text":"This keeps happening. I think part of me believes citrus counts as a plan."}]}]}','<p>Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.</p><p>This keeps happening. I think part of me believes citrus counts as a plan.</p>','Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be. This keeps happening. I think part of me believes citrus counts as a plan.',NULL,'Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a68q9fqaar06yexdd2tmm','quote','published','public',NULL,NULL,'From Seneca','https://en.wikiquote.org/wiki/Seneca_the_Younger','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copied this onto a sticky note and left it by the monitor for a week. It did its job."}]}]}','<p>Copied this onto a sticky note and left it by the monitor for a week. It did its job.</p>','Copied this onto a sticky note and left it by the monitor for a week. It did its job.','While we wait for life, life passes.',NULL,NULL,NULL,'pst_01km8a68q9fqaar06yexdd2tmm',NULL,1765352100,1765352100,1773778526,1773778526);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('pst_01km8a84x1fesa63bfv6m3rg45','note','published','public',NULL,NULL,'The Five-Minute Reset Is Still the Best Habit I Have',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dishes into the sink"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"clothes off the chair"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"papers into one stack"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"window cracked open"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"It does not fix everything, but it changes the room enough that I stop feeling stuck in it."}]}]}','<p>When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:</p><ul><li><p>dishes into the sink</p></li><li><p>clothes off the chair</p></li><li><p>papers into one stack</p></li><li><p>window cracked open</p></li></ul><p>It does not fix everything, but it changes the room enough that I stop feeling stuck in it.</p>','When the apartment starts feeling loud, I set a five-minute timer and do the same small loop: dishes into the sink clothes off the chair papers into one stack window cracked open It does not fix everything, but it changes the room enough that I stop feeling stuck in it.',NULL,'When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:
